function migrate(db2, list = migrations) {
  db2.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      id         INTEGER PRIMARY KEY,
      name       TEXT NOT NULL,
      applied_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `);
  const done = new Set(
    db2.prepare("SELECT id FROM schema_migrations").all().map((r) => r.id)
  );
  const applied = [];
  for (const m of [...list].sort((a, b) => a.id - b.id)) {
    if (done.has(m.id)) continue;
    transaction(db2, () => {
      db2.exec(m.sql);
      db2.prepare("INSERT INTO schema_migrations (id, name) VALUES (?, ?)").run(m.id, m.name);
    });
    applied.push(m.name);
  }
  return applied;
}

